// Holt beide Belege und korrigiert Menge + Preis-Zuordnung layout-unabhängig.
function rein(node) {
  const j = $(node).first().json;
  let beleg;
  if (j && j.belegtyp && Array.isArray(j.positionen)) beleg = j;
  else {
    const t = j?.output?.[0]?.content?.[0]?.text;
    if (t && typeof t === "object") beleg = t;
    else if (typeof t === "string") { try { beleg = JSON.parse(t); } catch(e){ beleg = j; } }
    else beleg = j;
  }

  if (beleg?.positionen) {
    for (const p of beleg.positionen) {
      const rab = (p.rabatt_prozent || 0) / 100;
      let ep = p.einzelpreis, gp = p.gesamtpreis;

      // Kandidaten für den Stück-Nettopreis (kleinerer der beiden geteilt macht keinen Sinn -
      // wir prüfen, welcher der beiden Werte der Einzelpreis ist).
      // Regel: Der Einzelpreis (vor Rabatt) ist der größere pro-Stück-Wert.
      // Menge ergibt sich als gesamt / (einzel * (1-rabatt)).
      function mengeFuer(einzel, gesamt){
        const netto = einzel * (1 - rab);
        return netto > 0 ? gesamt / netto : Infinity;
      }
      if (ep != null && gp != null) {
        // Variante A: ep=Einzelpreis, gp=Gesamtpreis  -> Menge sollte ganzzahlig sein
        const mA = mengeFuer(ep, gp);
        // Variante B: vertauscht
        const mB = mengeFuer(gp, ep);
        const abwA = Math.abs(mA - Math.round(mA)); // wie weit von ganzer Zahl?
        const abwB = Math.abs(mB - Math.round(mB));
        // Nur tauschen, wenn B DEUTLICH ganzzahliger ist als A und A unplausibel
        const plausibelA = mA >= 0.5 && mA < 1000 && abwA < 0.02;
        const plausibelB = mB >= 0.5 && mB < 1000 && abwB < 0.02;
        if (plausibelB && !plausibelA) { const t = ep; ep = gp; gp = t; }
      }

      // Menge deterministisch aus den (nun korrekten) Preisen
      const netto = ep * (1 - rab);
      if (netto > 0 && gp != null) {
        const m = Math.round(gp / netto);
        if (m > 0 && m < 1000) p.menge = m;
      }
      p.einzelpreis = ep;
      p.gesamtpreis = gp;
    }
  }
  return beleg;
}

const bestellung = rein("KI Extraktion Bestellung");
const ab         = rein("KI Extraktion AB");
return [{ json: { bestellung, ab } }];

// Vergleich Bestellung <-> AB. Findet Abweichungen bei Preis, Menge, Summe.
const data = $input.first().json;
const order = data.bestellung || {};
const conf  = data.ab || {};

const S = { IDENT:"identical", INFO:"info", OK:"probably_ok", DIFF:"difference" };
const near = (a,b) => (a==null||b==null) ? a===b : Math.abs(a-b) < 0.005;

// Preistoleranz aus dem Formular (in Prozent, optional). Leer oder ungültig = 0.
let toleranz = 0;
try {
  const roh = $('On form submission').first().json['Preistoleranz in Prozent'];
  const t = Number(String(roh ?? '').replace(',', '.'));
  if (Number.isFinite(t) && t > 0) toleranz = t;
} catch (e) { toleranz = 0; }
const de = n => String(n).replace('.', ',');

// Artikelnummer auf Modellkern reduzieren (8010, 8106, 1100 ...)
function kern(art){
  if(!art) return "";
  const m = String(art).toUpperCase().replace(/[^A-Z0-9]/g," ").match(/\b(\d{3,4})\b/);
  return m ? m[1] : String(art).toUpperCase();
}
// Konfig-Tokens (Stoff/Farbe) zum Unterscheiden gleicher Modelle
function tokens(p){
  const t = ((p.konfiguration||"")+" "+(p.artikelnummer||"")).toLowerCase();
  const set = new Set();
  ["stoff1","stoff2","stoff3","stoff4","stoff5","stoff7","stoff6"].forEach(s=>{ if(t.includes(s)) set.add(s); });
  ["schwarz","weiß","weiss","silber","moss","grau","black","white"].forEach(f=>{ if(t.includes(f)) set.add(f.replace("weiss","weiß").replace("black","schwarz").replace("white","weiß")); });
  (t.match(/\b\d{3}\b/g)||[]).forEach(n=>set.add(n));
  return set;
}
function score(a,b){
  const A=tokens(a), B=tokens(b); if(!A.size&&!B.size) return 0;
  let i=0; A.forEach(x=>{ if(B.has(x)) i++; }); return i/Math.max(A.size,B.size);
}

// Positionen matchen: nach Modellkern, dann per Konfig-Score
function match(op, cp){
  const pool = cp.map((p,i)=>({p,i,used:false}));
  const paare=[];
  for(const o of op){
    const k=kern(o.artikelnummer);
    const kand=pool.filter(c=>!c.used && kern(c.p.artikelnummer)===k);
    let best=null,bs=-1;
    for(const c of kand){
      let s=score(o,c.p)*100;
      if(o.menge===c.p.menge) s+=5;
      if(near(o.einzelpreis,c.p.einzelpreis)) s+=3;
      if(s>bs){bs=s;best=c;}
    }
    if(best){best.used=true; paare.push({order:o,conf:best.p});}
    else paare.push({order:o,conf:null});
  }
  for(const c of pool) if(!c.used) paare.push({order:null,conf:c.p});
  return paare;
}

// Mengen: immer exakt. Preise: Abweichung innerhalb der Toleranz = "wahrscheinlich ok".
function cmpNum(feld,a,b,istPreis=false){
  if(near(a,b)) return {feld,order:a,conf:b,status:S.IDENT,bemerkung:""};
  if(a==null||b==null) return {feld,order:a,conf:b,status:S.DIFF,bemerkung:"Wert fehlt in einem der Belege."};
  const diff = b-a;
  const prozent = a !== 0 ? Math.abs(diff/a)*100 : Infinity;
  if(istPreis && toleranz > 0 && prozent <= toleranz){
    return {feld,order:a,conf:b,status:S.OK,
      bemerkung:`Abweichung ${de(diff.toFixed(2))} (${de(prozent.toFixed(2))} %) – innerhalb der Toleranz von ${de(toleranz)} %.`};
  }
  const pz = Number.isFinite(prozent) ? ` / ${de(prozent.toFixed(2))} %` : "";
  return {feld,order:a,conf:b,status:S.DIFF,bemerkung:`Abweichung: ${de(a)} → ${de(b)} (${de(diff.toFixed(2))}${pz})`};
}

function gesamtStatus(liste){
  if(liste.some(d=>d.status===S.DIFF)) return S.DIFF;
  if(liste.some(d=>d.status===S.OK)) return S.OK;
  return S.IDENT;
}

const paare = match(order.positionen||[], conf.positionen||[]);
const positionen = paare.map(({order:o,conf:c})=>{
  const details=[];
  if(o&&c){
    details.push(cmpNum("Menge",o.menge,c.menge));
    details.push(cmpNum("Einzelpreis",o.einzelpreis,c.einzelpreis,true));
    details.push(cmpNum("Positionssumme",o.gesamtpreis,c.gesamtpreis,true));
  } else if(o&&!c){
    details.push({feld:"Position",order:`Pos ${o.pos}: ${o.artikelnummer}`,conf:"—",status:S.DIFF,bemerkung:"In AB nicht bestätigt."});
  } else {
    details.push({feld:"Position",order:"—",conf:`Pos ${c.pos}: ${c.artikelnummer}`,status:S.DIFF,bemerkung:"Zusätzlich in AB, nicht bestellt."});
  }
  return {
    posBE:o?.pos||null, posAB:c?.pos||null,
    titel:(o?.bezeichnung||c?.bezeichnung||""),
    artBE:o?.artikelnummer||"", artAB:c?.artikelnummer||"",
    status: gesamtStatus(details), details
  };
});

const kopf = [
  cmpNum("Nettogesamtbetrag", order.meta?.netto_gesamt, conf.meta?.netto_gesamt, true),
];

// Kontrollrechnung je Beleg: Summe der Positionen gegen die genannte Nettosumme.
// Weicht sie ab, wurde evtl. falsch ausgelesen oder der Beleg selbst ist fehlerhaft.
for (const [name, beleg] of [["Bestellung", order], ["Auftragsbestätigung", conf]]) {
  const summe = (beleg.positionen||[]).reduce((s,p)=>s+(Number(p.gesamtpreis)||0),0);
  const netto = beleg.meta?.netto_gesamt;
  if (netto != null && Math.abs(summe - netto) >= 0.01) {
    kopf.push({feld:`Summenkontrolle ${name}`, order:summe, conf:netto, status:S.INFO,
      bemerkung:`Summe der Positionen (${de(summe.toFixed(2))}) ≠ Nettosumme laut Beleg (${de(Number(netto).toFixed(2))}). Beleg manuell prüfen.`});
  }
}

const anzahlDiff = positionen.filter(p=>p.status===S.DIFF).length
                 + kopf.filter(k=>k.status===S.DIFF).length;

return [{ json: {
  bestellnummer: order.meta?.bestellnummer || conf.meta?.bestellnummer || "",
  ab_nummer: conf.meta?.ab_nummer || "",
  lieferant: (conf.anschriften?.lieferant||"").split(",")[0],
  toleranz_prozent: toleranz,
  anzahl_abweichungen: anzahlDiff,
  kopf,
  positionen
}}];

// Baut aus dem Vergleichsergebnis das HTML-Prüfprotokoll – inkl. Feedback-Button.
const d = $input.first().json;
const ICON = { identical:"✅", info:"ℹ️", probably_ok:"🔶", difference:"🔺" };
const esc = s => String(s ?? "").replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const eur = n => (n==null?"":Number(n).toLocaleString("de-DE",{minimumFractionDigits:2,maximumFractionDigits:2}));

// Feedback-Formular-Adresse + Bestellnummer vorausgefüllt
// Nach dem Import ersetzen: Production-URL des Formulars aus dem Workflow "Belegabgleich Feedback".
const FEEDBACK_URL = "https://YOUR-N8N-INSTANCE/form/YOUR-FEEDBACK-FORM-ID";
const feedbackLink = FEEDBACK_URL + "?Beleg%20(Bestellnummer%20%2F%20AB-Nummer)=" + encodeURIComponent((d.bestellnummer||"") + " / " + (d.ab_nummer||""));

const ampel = d.anzahl_abweichungen > 0
  ? `${d.anzahl_abweichungen} Abweichung(en) gefunden – bitte prüfen.`
  : "Keine Abweichungen gefunden.";
const ampelClass = d.anzahl_abweichungen > 0 ? "difference" : "identical";

const kopfRows = (d.kopf||[]).map(r => `<tr class="status-${r.status}">
  <td class="st">${ICON[r.status]}</td><td class="field">${esc(r.feld)}</td>
  <td>${eur(r.order)}</td><td>${eur(r.conf)}</td><td class="ki">${esc(r.bemerkung)}</td></tr>`).join("");

const posBlocks = (d.positionen||[]).map(p => {
  const rows = p.details.map(x => `<tr class="status-${x.status}">
    <td class="st">${ICON[x.status]}</td><td class="field">${esc(x.feld)}</td>
    <td>${typeof x.order==="number"?eur(x.order):esc(x.order)}</td>
    <td>${typeof x.conf==="number"?eur(x.conf):esc(x.conf)}</td>
    <td class="ki">${esc(x.bemerkung)}</td></tr>`).join("");
  return `<div class="pos status-${p.status}">
    <div class="pos-head">${ICON[p.status]} <strong>${esc(p.titel)}</strong>
      <span class="ref">Bestellung Pos ${esc(p.posBE??"—")} · AB Pos ${esc(p.posAB??"—")}</span></div>
    <div class="art">Artikelnr. Bestellung: <b>${esc(p.artBE)}</b> · AB: <b>${esc(p.artAB)}</b></div>
    <table><thead><tr><th></th><th>Feld</th><th>Bestellung</th><th>Auftragsbestätigung</th><th>Bemerkung</th></tr></thead>
    <tbody>${rows}</tbody></table></div>`;
}).join("");

const html = `<!doctype html><html lang="de"><head><meta charset="utf-8">
<title>Prüfprotokoll AB ${esc(d.ab_nummer)} zu Bestellung ${esc(d.bestellnummer)}</title>
<style>
body{font-family:Arial,sans-serif;color:#111;max-width:1000px;margin:0 auto;padding:16px}
h1{font-size:20px}.disc{font-size:13px;color:#555;margin-bottom:10px}
.ampel{display:inline-block;font-weight:700;padding:8px 14px;border-radius:8px;margin:8px 0}
.ampel.difference{background:#fff1f2;color:#dc2626}.ampel.identical{background:#f0fdf4;color:#15803d}
.legend{font-size:12px;color:#555;margin:6px 0}
table{width:100%;border-collapse:collapse;font-size:13px;margin-top:6px}
th,td{border-bottom:1px solid #e5e7eb;padding:7px 9px;text-align:left;vertical-align:top}
th{background:#f8fafc;font-size:12px}.field{font-weight:600}.st{width:36px}.ki{color:#374151;font-size:12px}
.status-difference{background:#fff1f2}
.status-probably_ok{background:#fffbeb}
.status-info{background:#eff6ff}
.pos{border:1px solid #e5e7eb;border-radius:8px;padding:10px;margin:12px 0}
.pos-head{font-weight:700;margin-bottom:2px}.ref{font-size:12px;color:#475569;background:#e2e8f0;border-radius:999px;padding:2px 8px;margin-left:6px;font-weight:700}
.art{font-size:12px;color:#555;margin-bottom:6px}
.section{margin-top:18px;font-weight:700;font-size:15px}
.fb{margin-top:24px;padding:16px;background:#f8fafc;border:1px solid #e5e7eb;border-radius:8px;text-align:center}
.fb a{display:inline-block;background:#ef7a1a;color:#fff;text-decoration:none;font-weight:700;padding:11px 20px;border-radius:7px}
.fb p{font-size:12px;color:#555;margin:8px 0 0}
</style></head><body>
<h1>KI-Prüfprotokoll der Auftragsbestätigung ${esc(d.ab_nummer)} zur Bestellung ${esc(d.bestellnummer)}</h1>
<p class="disc">Lieferant: ${esc(d.lieferant)} · Eine KI kann Fehler machen – bitte prüfen Sie alle Werte sorgfältig. Keine Haftung.</p>
<div class="ampel ${ampelClass}">${ampel}</div>
<div class="legend">✅ Identisch &nbsp; 🔶 Innerhalb der Preistoleranz &nbsp; ℹ️ Hinweis (Summenkontrolle) &nbsp; 🔺 Abweichung${d.toleranz_prozent ? ` &nbsp;·&nbsp; Preistoleranz: ${esc(String(d.toleranz_prozent).replace('.', ','))} %` : ""}</div>
<div class="section">Kopfinformationen</div>
<table><thead><tr><th></th><th>Feld</th><th>Bestellung</th><th>Auftragsbestätigung</th><th>Bemerkung</th></tr></thead><tbody>${kopfRows}</tbody></table>
<div class="section">Positionsvergleich</div>
${posBlocks}
<div class="fb">
  <a href="${feedbackLink}" target="_blank">Feedback geben / Positionen korrigieren</a>
  <p>Öffnet ein Formular, in dem Sie fehlerhafte Positionen und Kommentare für künftige Prüfungen hinterlegen können.</p>
</div>
</body></html>`;

return [{ json: { html, betreff: `Prüfprotokoll AB ${d.ab_nummer} zu Bestellung ${d.bestellnummer} – ${d.anzahl_abweichungen} Abweichung(en)` } }];
